From b8d0278f906517486805fd070804850560678407 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:24:58 +0100
Subject: [PATCH] applet: always show the device of each application stream

The device an application plays to or records from was only shown when
hovering its name, so seeing where each stream goes meant checking them
one by one. Show the device name dimmed next to the stream's menu button.

BUG: 495050
---
 applet/ListItemBase.qml   | 24 ++++++++++++++++++++++--
 applet/StreamListItem.qml |  2 +-
 2 files changed, 23 insertions(+), 3 deletions(-)

diff --git a/applet/ListItemBase.qml b/applet/ListItemBase.qml
index 83fab21f..1dee0d1e 100644
--- a/applet/ListItemBase.qml
+++ b/applet/ListItemBase.qml
@@ -25,6 +25,7 @@ PC3.ItemDelegate {
     // TODO: convert to a proper enum?
     property string /* "sink" | "sink-input" | "source" | "source-output" */ type
     property string fullNameToShowOnHover: ""
+    property string deviceName: ""
     readonly property bool isStream: item.type === "sink-input" || item.type === "source-output"

     highlighted: dropArea.containsDrag
@@ -146,7 +147,7 @@ PC3.ItemDelegate {
                         ? (defaultButton.Layout.leftMargin - Layout.margins) + defaultButton.indicator.width + defaultButton.spacing
                         : Layout.margins
                     visible: !defaultButton.visible
-                    implicitHeight: Math.max(friendlyDescriptionLabel.implicitHeight, longDescriptionLabel.implicitHeight)
+                    implicitHeight: Math.max(friendlyDescriptionLabel.implicitHeight, longDescriptionLabel.implicitHeight, deviceNameLabel.implicitHeight)

                     // User-friendly name
                     PC3.Label {
@@ -156,7 +157,9 @@ PC3.ItemDelegate {
                             left: parent.left
                             verticalCenter: parent.verticalCenter
                         }
-                        width: Math.min(implicitWidth, parent.width)
+                        width: Math.min(implicitWidth, deviceNameLabel.visible
+                            ? Math.max(parent.width / 2, parent.width - deviceNameLabel.implicitWidth - Kirigami.Units.smallSpacing)
+                            : parent.width)

                         text: item.label
                         textFormat: Text.PlainText
@@ -193,6 +196,23 @@ PC3.ItemDelegate {
                         textFormat: Text.PlainText
                         elide: Text.ElideRight
                     }
+
+                    // Device the stream plays to or records from
+                    PC3.Label {
+                        id: deviceNameLabel
+
+                        anchors {
+                            right: parent.right
+                            verticalCenter: parent.verticalCenter
+                        }
+                        width: Math.min(implicitWidth, parent.width - friendlyDescriptionLabel.width - Kirigami.Units.smallSpacing)
+
+                        visible: text !== ""
+                        opacity: 0.75
+                        text: item.deviceName
+                        textFormat: Text.PlainText
+                        elide: Text.ElideRight
+                    }
                 }

                 SmallToolButton {
diff --git a/applet/StreamListItem.qml b/applet/StreamListItem.qml
index b3df1899..f8e7d3f9 100644
--- a/applet/StreamListItem.qml
+++ b/applet/StreamListItem.qml
@@ -36,7 +36,7 @@ ListItemBase {
             return i18n("Stream name not found");
         }
     }
-    fullNameToShowOnHover: {
+    deviceName: {
         if (devicesModel.count > 1) {
             const indexRole = devicesModel.KItemModels.KRoleNames.role("Index");
             const descriptionRole = devicesModel.KItemModels.KRoleNames.role("Description");
-- 
